import json, urllib.request, urllib.parse
def get(url):
    with urllib.request.urlopen(url, timeout=60) as r:
        return json.load(r)
g = get("https://gtexportal.org/api/v2/reference/gene?geneId=INS&page=0&itemsPerPage=20")
for x in g.get("data", []):
    print(x.get("geneSymbol"), x.get("gencodeId"), x.get("chromosome"), x.get("geneType"))

for ds in ["gtex_v10","gtex_v8"]:
    for gid in ["ENSG00000254647.6","ENSG00000254647"]:
        u=f"https://gtexportal.org/api/v2/expression/medianGeneExpression?gencodeId={gid}&datasetId={ds}&page=0&itemsPerPage=100"
        try:
            d=get(u); print(ds, gid, "rows:", len(d.get("data",[])))
        except Exception as e:
            print(ds, gid, "ERR", e)

d=get("https://gtexportal.org/api/v2/expression/medianGeneExpression?gencodeId=ENSG00000254647.6&datasetId=gtex_v8&page=0&itemsPerPage=100")
rows=sorted(d["data"], key=lambda x:-x["median"])
print("dataset:", rows[0].get("datasetId"), "| unit:", rows[0].get("unit"), "| n:", len(rows))
for x in rows[:8]: print(f'{x["tissueSiteDetailId"]:40s} {x["median"]:>12.3f}')
print("--- lowest ---")
for x in rows[-3:]: print(f'{x["tissueSiteDetailId"]:40s} {x["median"]:>12.3f}')
